// cod3mp: campaign-only functions the shared files name.
// Generated by tools/mp_aliases.py from mp/config/campaign_map.tsv; edit the
// table and run the tool, not this file.
//
// Each one is the original of a hook that only the campaign uses (a page,
// a film, a battle action ...). Nothing in cod3mp calls them; if one ever
// ran, the log names it once and it returns 0.

#include <atomic>

#include <rex/hook.h>
#include <rex/logging.h>

namespace {
void Trap(PPCContext& ctx, const char* name) {
  static std::atomic<bool> logged{false};
  if (!logged.exchange(true)) REXLOG_ERROR("cod3mp: campaign-only code ran: {}", name);
  ctx.r3.u64 = 0;
}
}  // namespace


